        const currentScript = scripts[scripts.length - 1];
        const scope = currentScript.previousElementSibling;
        if (!scope) return;
        const paperStack = scope.querySelector('.mp-paper-stack');
        const bodyWrapper = scope.querySelector('.mp-body-wrapper');
        const themeToggle = scope.querySelector('#themeToggle');
        const scopeContainer = scope;

        if (paperStack && bodyWrapper) {
            paperStack.addEventListener('click', function(e) {
                if (e.target === themeToggle || themeToggle.contains(e.target)) return;
                if (window.getSelection().toString().length > 0) return;
                e.stopPropagation();
                bodyWrapper.classList.toggle('is-collapsed');
                paperStack.classList.toggle('is-folded');
            });
        }

        if (themeToggle) {
            themeToggle.addEventListener('click', function(e) {
                e.stopPropagation();
                if (scopeContainer.classList.contains('theme-light')) {
                    scopeContainer.classList.remove('theme-light');
                    scopeContainer.classList.add('theme-dark');
                } else {
                    scopeContainer.classList.remove('theme-dark');
                    scopeContainer.classList.add('theme-light');
                }
            });
        }
