<script>
(function() {
    // Trình quan sát kiểu dáng toàn cục độ chính xác cao
    try {
        if (window.parent && window.parent !== window) {
            var _syncTheme = function() {
                try {
                    var pd = window.parent.document;
                    var pwin = window.parent;
                    var proot = pd.documentElement;
                    var pbody = pd.body;
                    var target = pd.querySelector('.mes_text') || pd.querySelector('#chat') || pbody;

                    var rootStyle = pwin.getComputedStyle(proot);
                    var targetStyle = pwin.getComputedStyle(target);
                    var bodyStyle = pwin.getComputedStyle(pbody);

                    var tc = rootStyle.getPropertyValue('--SmartThemeTextColor').trim();
                    if (!tc || tc.indexOf('var(') === 0) {
                        tc = targetStyle.color || bodyStyle.color;
                    }
                    if (tc && tc.indexOf('var(') !== 0) {
                        document.documentElement.style.setProperty('--st-text', tc);
                    }
                    var fw = rootStyle.getPropertyValue('--mainFontWeight').trim() || targetStyle.fontWeight || bodyStyle.fontWeight;
                    if (fw) {
                        document.documentElement.style.setProperty('--st-font-weight', fw);
                    }
                    var fs = rootStyle.getPropertyValue('--mainFontSize').trim() || targetStyle.fontSize || bodyStyle.fontSize;
                    if (fs) {
                        document.documentElement.style.setProperty('--st-font-size', fs);
                    }
                } catch (e) {}
            };
            _syncTheme();
            var _obs = new MutationObserver(_syncTheme);
            _obs.observe(window.parent.document.documentElement, { attributes: true, attributeFilter: ['style', 'class'] });
            _obs.observe(window.parent.document.body, { attributes: true, attributeFilter: ['style', 'class'] });
            setInterval(_syncTheme, 1200);
        }
    } catch (_e) {}

    const uid = Math.random().toString(36).substring(2, 10);
    const scriptRoot = document.currentScript.parentElement;
    const container = scriptRoot.querySelector('.options-container');
    const rawData = scriptRoot.querySelector('.st-raw-data');
    const detailsEl = scriptRoot.querySelector('.st-action-details');

    let selectedOptions = [];

    function updateIframeHeight() {
        setTimeout(function() {
            var bodyHeight = document.body.scrollHeight;
            if (window.parent && window.parent !== window) {
                window.parent.postMessage({ type: 'resizeIframe', height: bodyHeight }, '*');
            }
        }, 50);
    }

    if (detailsEl) {
        detailsEl.addEventListener('toggle', updateIframeHeight);
    }

    function getSTInputBox() {
        try { 
            return window.parent?.document?.querySelector('#send_textarea') || 
                   document.querySelector('#send_textarea'); 
        } catch (e) { 
            return document.querySelector('#send_textarea'); 
        }
    }

    function syncToInput() {
        const finalText = selectedOptions.map(card => card.dataset.text).join('\n\n');
        const inputBox = getSTInputBox();
        if (inputBox) {
            inputBox.value = finalText;
            inputBox.dispatchEvent(new Event('input', { bubbles: true }));
            inputBox.dispatchEvent(new Event('change', { bubbles: true }));
            inputBox.focus();
        }
    }

    function buildOptions() {
        if (!container || !rawData) return;
        const rawText = rawData.innerHTML || rawData.textContent;
        const parts = rawText.split(/<br\s*\/?>/i);
        let optionCount = 0;

        parts.forEach(part => {
            let text = part.replace(/<[^>]+>/g, '').trim();
            if (!text) return;

            optionCount++;
            const card = document.createElement('div');
            card.className = 'option-card';

            // Khớp tiền tố số thứ tự tùy chọn ở đầu dòng + bất kỳ ký hiệu [...] hoặc [...] nào
            const bracketMatch = text.match(/^\s*(?:[①-⑳\d.、\-]|Tùy\s*chọn|Thứ|Mục|Cái)*\s*[【\[](.*?)[】\]]([\s\S]*)/);
            let badgeHtml = "";
            let desc = "";

            if (bracketMatch) {
                const inner = bracketMatch[1].trim();
                desc = bracketMatch[2].trim();

                // Xác định các dấu phân cách phổ biến và thực hiện chia tách nội dung
                const separatorRegex = /[·・|｜:：-]/;
                const innerParts = inner.split(separatorRegex);

                if (innerParts.length > 1) {
                    // Tồn tại dấu phân cách, chỉ trích xuất văn bản phía sau dấu phân cách cuối cùng làm thẻ tiêu đề phụ
                    const tag = innerParts[innerParts.length - 1].trim();
                    badgeHtml = `<div class="option-badge">${optionCount} · ${tag}</div>`;
                } else {
                    // Khi không có dấu phân cách, loại trừ số thứ tự thuần túy và tiền tố số thứ tự vô dụng được cài đặt sẵn (như 1, Tùy chọn 1, Mục 1, v.v.)
                    const isNumericOnly = /^(?:Tùy\s*chọn|Thứ|no\.?|option)?\s*\d+\s*(?:Mục|Cái)?$/i.test(inner);
                    if (isNumericOnly) {
                        badgeHtml = `<div class="option-badge">Tùy chọn ${optionCount}</div>`;
                    } else {
                        badgeHtml = `<div class="option-badge">${optionCount} · ${inner}</div>`;
                    }
                }
            } else {
                // Nếu hoàn toàn không có định dạng [...], thì sử dụng số thứ tự mặc định
                desc = text;
                badgeHtml = `<div class="option-badge">Tùy chọn ${optionCount}</div>`;
            }

            card.dataset.text = desc;
            card.innerHTML = `${badgeHtml}<div class="option-text">${desc}</div>`;

