                if (this.classList.contains('selected')) {
                    this.classList.remove('selected');
                    selectedOptions = selectedOptions.filter(c => c !== this);
                } else {
                    this.classList.add('selected');
                    selectedOptions.push(this);
                }
                syncToInput();
                updateIframeHeight();
            });

            container.appendChild(card);
        });

        const countBadge = scriptRoot.querySelector('#st-opt-count');
        if (countBadge) countBadge.textContent = optionCount;
        updateIframeHeight();
    }

    buildOptions();
})();
</script>
